INSERT INTO collection_pages VALUES('182d751f9f0afe0ebc5a2f8173cb86953fa9a5df0edcc459f143b81afb980584','900b9ecb128858d8557da92a1e311fc892bc3f3d369bc943a04721cd044b3343','{"hasNext":false,"items":[{"author":{"account":{"login":"omer-arafat","providerType":"User"},"email":"155361435+omer-arafat@users.noreply.github.com","name":"omer-arafat"},"authoredDate":"2026-05-09T08:22:45Z","committedDate":"2026-05-09T08:22:45Z","committer":{"account":{"login":"omer-arafat","providerType":"User"},"email":"155361435+omer-arafat@users.noreply.github.com","name":"omer-arafat"},"observedAt":"2026-10-08T22:57:21.572Z","repositoryId":1233684158,"sha":"d82f19bfd664c4f475bfa36bc76ac4b7d28b10aa"}],"observedAt":"2026-10-08T22:57:21.572Z","raw":[{"author":{"avatar_url":"https://avatars.githubusercontent.com/u/155361435?v=4","events_url":"https://api.github.com/users/omer-arafat/events{/privacy}","followers_url":"https://api.github.com/users/omer-arafat/followers","following_url":"https://api.github.com/users/omer-arafat/following{/other_user}","gists_url":"https://api.github.com/users/omer-arafat/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/omer-arafat","id":155361435,"login":"omer-arafat","node_id":"U_kgDOCUKgmw","organizations_url":"https://api.github.com/users/omer-arafat/orgs","received_events_url":"https://api.github.com/users/omer-arafat/received_events","repos_url":"https://api.github.com/users/omer-arafat/repos","site_admin":false,"starred_url":"https://api.github.com/users/omer-arafat/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/omer-arafat/subscriptions","type":"User","url":"https://api.github.com/users/omer-arafat","user_view_type":"public"},"comments_url":"https://api.github.com/repos/arafatomer66/splendid-canyon/commits/d82f19bfd664c4f475bfa36bc76ac4b7d28b10aa/comments","commit":{"author":{"date":"2026-05-09T08:22:45Z","email":"155361435+omer-arafat@users.noreply.github.com","name":"omer-arafat"},"comment_count":0,"committer":{"date":"2026-05-09T08:22:45Z","email":"155361435+omer-arafat@users.noreply.github.com","name":"omer-arafat"},"message":"Initial commit: micro-frontend + microservice learning sandbox\n\nMini e-commerce demo combining Angular Native Federation MFEs with\nExpress + Kafka microservices. Designed for learning, with deep-dive\ndocs in docs/ and a guided walkthrough.\n\nArchitecture:\n- 4 Angular 20 MFEs (shell + 3 federated remotes) on ports 4200-4203\n- 5 Express services (gateway + 4 bounded contexts) on ports 8080-8084\n- Kafka 3.7 KRaft mode for async events (cart-events, order-events,\n  user-events) with userId as partition key\n- SQLite per service (database-per-service pattern)\n- HS256 JWT auth, gateway verifies and injects x-user-id\n\nLearning materials in docs/:\n- 01: micro-frontends concept primer\n- 02: microservices concept primer\n- 03: Native Federation deep dive\n- 04: Kafka events (topics, partitions, consumer groups)\n- 05: end-to-end walkthrough with running system\n- 06: honest trade-offs discussion\n\nEach piece is fully decoupled — own package.json, no workspace root,\nno shared lib. Designed to be runnable standalone (npm start per folder)\nor via docker-compose.\n\nCo-Authored-By: Claude Opus 4.7 (1M context) <noreply@anthropic.com>","tree":{"sha":"0a08e3b3f15d8186ece71060598162e49733f24f","url":"https://api.github.com/repos/arafatomer66/splendid-canyon/git/trees/0a08e3b3f15d8186ece71060598162e49733f24f"},"url":"https://api.github.com/repos/arafatomer66/splendid-canyon/git/commits/d82f19bfd664c4f475bfa36bc76ac4b7d28b10aa","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/155361435?v=4","events_url":"https://api.github.com/users/omer-arafat/events{/privacy}","followers_url":"https://api.github.com/users/omer-arafat/followers","following_url":"https://api.github.com/users/omer-arafat/following{/other_user}","gists_url":"https: